UPDATE noticias SET
title='Corte de San Martín conmemoró el Día del Juez y la Jueza con ceremonia solemne',
summary='Ceremonia en Moyobamba con homenaje a magistrados y reconocimiento a los órganos jurisdiccionales que superaron sus metas de producción.',
body='La Corte Superior de Justicia de San Martín conmemoró el Día del Juez y la Jueza con una ceremonia solemne en Moyobamba, con liturgia de acción de gracias, reseña histórica de la fecha instituida por el Decreto Ley N. 18918 y el reconocimiento a los órganos jurisdiccionales que alcanzaron y superaron las metas de producción.'
WHERE id='oficial-dia-juez-2026';
UPDATE noticias SET
title='Juzgado de Tarapoto condena a 35 años de prisión a dos coautores de asesinato',
summary='El Juzgado Penal Colegiado de Tarapoto condenó a dos coautores del asesinato del empresario Jaime Ramírez Navarro, con reparación civil de S/ 101 000.',
body='El Juzgado Penal Colegiado Supraprovincial Permanente de Tarapoto condenó a 35 años de pena privativa de libertad a dos coautores de los delitos de homicidio calificado y robo agravado, con reparación civil de S/ 101 000, inhabilitación para portar armas y captura inmediata para la ejecución de la pena.'
WHERE id='oficial-condena-35-2026';
UPDATE noticias SET
title='Corte de San Martín obtiene tercer lugar en concurso nacional de fotografía',
summary='La fotografía premiada, titulada "Escuchar para proteger", retrata una jornada de justicia itinerante en la comunidad nativa de Canoapuerto.',
body='La Corte obtuvo el tercer lugar en el concurso nacional de fotografía "Justicia que Trasciende", en el I Congreso Nacional de Justicia Itinerante. La fotografía "Escuchar para proteger", de la Oficina de Imagen Institucional, retrata una jornada itinerante en la comunidad nativa de Canoapuerto con el pueblo indígena Shawi.'
WHERE id='oficial-foto-2026';
UPDATE noticias SET
title='Corte de San Martín impulsa jornada educativa sobre la ruta de la flagrancia delictiva',
summary='Estudiantes conocieron de manera vivencial el funcionamiento del sistema de justicia y reflexionaron sobre la prevención del delito.',
body='La Corte Superior de Justicia de San Martín desarrolló una jornada educativa dirigida a estudiantes de secundaria, como parte de las acciones orientadas a fortalecer la cultura de legalidad y prevenir el delito entre adolescentes.\n\nLa actividad acercó a las y los estudiantes al funcionamiento del sistema de justicia y promovió la reflexión sobre sus derechos y responsabilidades.'
WHERE id='official-1415894';
UPDATE noticias SET
title='Corte presenta buenas prácticas digitales en feria nacional de Huánuco',
summary='Transcriptor de audiencias con IA, automatización de remates y DepoFile ante diez cortes del país.',
body='En la III Feria de Transformación Digital Judicial de Huánuco, la Corte presentó el transcriptor de audiencias con inteligencia artificial, la automatización de remates judiciales electrónicos y el software DepoFile para depósitos judiciales, ante la Presidenta del Poder Judicial y diez cortes del país.'
WHERE id='oficial-feria-digital-2026';
UPDATE noticias SET
title='Presidente de la Corte gestiona terreno para moderno laboratorio de criminalística en Tarapoto',
summary='Terreno de 5 000 m2 en Cacatachi para peritajes biológicos, químicos y balísticos sin derivar muestras a otras ciudades.',
body='El presidente de la Corte gestionó ante la Municipalidad Provincial de San Martín la donación de un terreno de aproximadamente 5 000 metros cuadrados en el distrito de Cacatachi para construir un moderno laboratorio de criminalística con ambientes de peritajes biológicos, químicos, balísticos y de alta complejidad.'
WHERE id='oficial-laboratorio-2026';
UPDATE noticias SET
title='Corte fortalece la justicia con promoción y designación de magistrados',
summary='Magistrados provisionales y supernumerarios en Moyobamba, Juanjuí y Yurimaguas garantizan la continuidad del servicio.',
body='La Presidencia dispuso la promoción y designación de magistrados provisionales y supernumerarios en órganos jurisdiccionales de Moyobamba, Juanjuí y Yurimaguas, tras la designación de magistrados como presidentes de Jurados Electorales Especiales, asegurando la continuidad del servicio de justicia.'
WHERE id='oficial-magistrados-2026';
